-- Reason: Snowflake has no SET/MULTISET table kinds (all tables allow duplicate rows). Snowflake has no primary index; micro-partitioning distributes data automatically, so the hashing/distribution clause has no target equivalent.
CREATE TABLE SALES.TRANSFER (TRANSFER_ID BIGINT, FROM_ACCOUNT BIGINT, TO_ACCOUNT BIGINT);

