-- Converted: CREATE INDEX sales.ix_customer_status (status) ON sales.customer -> ALTER TABLE SALES.CUSTOMER CLUSTER BY (STATUS).
-- Reason: CREATE INDEX only applies to Snowflake hybrid tables (rule snowflake.rule.no_create_index); a clustering key on the indexed column is the standard-table replacement for a non-unique secondary index.
ALTER TABLE SALES.CUSTOMER CLUSTER BY (STATUS);

-- Converted: CREATE UNIQUE INDEX sales.ix_account_customer (customer_id) ON sales.account -> named UNIQUE constraint on SALES."ACCOUNT" (CUSTOMER_ID).
-- Reason: Snowflake has no CREATE INDEX on standard tables; a UNIQUE constraint records the uniqueness intent (informational, not enforced).
ALTER TABLE SALES."ACCOUNT" ADD CONSTRAINT IX_ACCOUNT_CUSTOMER UNIQUE (CUSTOMER_ID);

-- Converted: lookup access path of the unique index -> search optimization on equality predicates for CUSTOMER_ID.
-- Reason: Search optimization is the Snowflake replacement for selective point-lookup indexes on standard tables.
ALTER TABLE SALES."ACCOUNT" ADD SEARCH OPTIMIZATION ON EQUALITY(CUSTOMER_ID);

-- Converted: CREATE HASH INDEX sales.hix_account (account_id) ON sales.account BY (customer_id) -> ALTER TABLE SALES."ACCOUNT" CLUSTER BY (CUSTOMER_ID).
-- Reason: Snowflake has no hash indexes; the BY (customer_id) distribution clause is a co-location request, which maps to a clustering key on the same column.
ALTER TABLE SALES."ACCOUNT" CLUSTER BY (CUSTOMER_ID);

-- Converted: CREATE HASH INDEX sales.hix_card (card_id) ON sales.card -> search optimization on equality predicates for SALES.CARD.CARD_ID.
-- Reason: Snowflake has no hash indexes; a hash index without BY is a lookup structure on a high-cardinality key, which search optimization replaces (clustering on a near-unique key is not recommended).
ALTER TABLE SALES.CARD ADD SEARCH OPTIMIZATION ON EQUALITY(CARD_ID);
